@import 'tailwindcss';
@import 'tw-animate-css';
@import './motion.css';

:root {
  --background: #0c0b09; --foreground: #f3ebdd; --card: #181610; --card-foreground: #f3ebdd;
  --popover: #211d15; --popover-foreground: #f3ebdd; --primary: #c8a45c; --primary-foreground: #18130b;
  --secondary: #292419; --secondary-foreground: #f3ebdd; --muted: #211d15; --muted-foreground: #b7aa94;
  --accent: #3b3020; --accent-foreground: #f0d99e; --destructive: #d48b76; --border: #55432b;
  --input: #55432b; --ring: #f0d99e; --radius: 4px;
  --sidebar: #181610; --sidebar-foreground: #f3ebdd;
  --gold-shadow: #735427; --gold: #c8a45c; --gold-light: #f0d99e;
  --left-width: 272px; --right-width: 320px; --gap: 12px; --header-height: 68px; --notice-height: 32px;
  --title-border: #93703a; --title-ornament-opacity: 1;
}
@theme inline {
  --color-background: var(--background); --color-foreground: var(--foreground); --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground); --color-muted: var(--muted); --color-muted-foreground: var(--muted-foreground);
  --color-border: var(--border); --color-ring: var(--ring); --font-sans: var(--font-ui);
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; background: var(--background); color: var(--foreground); }
body { font-size: 14px; line-height: 1.5; }
button, input { font-family: var(--font-ui); }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; }
button:focus-visible, input:focus-visible, [tabindex]:focus-visible { outline: 2px solid var(--gold-light); outline-offset: 3px; }
svg { width: 18px; height: 18px; stroke-width: 1.65; flex-shrink: 0; }
.num { font-variant-numeric: tabular-nums; }
.muted { color: var(--muted-foreground); }
.shell { height: 100dvh; min-width: 1580px; display: flex; flex-direction: column; }
.topbar { flex: 0 0 var(--header-height); display: flex; align-items: stretch; padding: 0 24px; gap: 44px; background: linear-gradient(#242017, #12110e); border-bottom: 1px solid #836432; box-shadow: 0 1px 0 #070604, 0 4px 20px #0008; z-index: 2; }
.wordmark { display: flex; align-items: center; gap: 12px; width: 224px; flex-shrink: 0; }
.brand-glyph { width: 32px; height: 32px; display: grid; place-items: center; transform: rotate(45deg); border: 1px solid #d3b371; box-shadow: inset 0 0 0 4px #1c180f, inset 0 0 0 5px #75592e; }
.brand-glyph span { transform: rotate(-45deg); color: #eed498; font-family: Georgia, serif; font-size: 23px; }
.brand-name { font-family: Georgia, serif; font-size: 28px; letter-spacing: 4px; color: #ead49f; line-height: 1.1; }
.brand-caption { margin-top: 3px; color: #968468; font-size: 10px; letter-spacing: 3.7px; }
.primary-nav { display: flex; align-items: stretch; gap: 29px; flex: 1; }
.primary-nav button { position: relative; border: 0; background: none; color: #b7aa94; font-size: 16px; font-weight: 700; padding: 0 5px; white-space: nowrap; }
.primary-nav button:hover { color: #f3ebdd; }
.primary-nav button[aria-pressed=true] { color: #f0d99e; background: linear-gradient(0deg,#a67b2924,transparent 65%); }
.primary-nav button[aria-pressed=true]::after { content: ''; height: 3px; background: linear-gradient(90deg,#6e5025,#f2daa0,#6e5025); position: absolute; bottom: -1px; left: 0; right: 0; box-shadow: 0 -4px 16px #d6ac5244; }
.nav-dot { display:inline-block; width: 5px; height: 5px; background: #f0d99e; border-radius: 50%; margin-right: 7px; vertical-align: 3px; }
.header-account { display:flex; align-items:center; gap: 9px; }
.btn { min-height: 36px; height:auto; border-radius: 3px; border:1px solid #685132; padding:7px 12px; font-size:14px; background:linear-gradient(#342c1f,#201b13); color:#eadab9; box-shadow:inset 0 1px 0 #b293532d,0 2px 3px #0005; transition:background 150ms,box-shadow 150ms; }
.btn:hover { background:linear-gradient(#4b3c26,#302719); box-shadow:inset 0 1px 0 #d9bc7660,0 0 16px #b38b3420; }
.btn:active { box-shadow:inset 0 3px 6px #0009; transform:translateY(1px); }
.btn.gold { color:#231b0d; border-color:#d8bd7f; font-weight:800; background:linear-gradient(115deg,#b58a42,#ecd6a0 48%,#b5914d); text-shadow:0 1px 0 #fff4; }
.btn:disabled { opacity:1; color:#938774; background:#211e18; border-color:#3c3427; box-shadow:inset 0 1px 0 #ffffff05; pointer-events:auto; transform:none; }
.noticebar { flex:0 0 var(--notice-height); display:flex; align-items:center; justify-content:space-between; padding:0 24px; background:#14120f; border-bottom:1px solid #332b1e; color:#b7aa94; font-size:12px; }
.noticebar > span { display:flex; align-items:center; gap:10px; }
.noticebar svg { width:13px; height:13px; color:#c8a45c; }
.noticebar b { font-weight:500; color:#cfb575; }
.workspace { flex:1; min-height:0; display:grid; grid-template-columns:var(--left-width) minmax(0,1fr) var(--right-width); gap:var(--gap); padding:12px; background:radial-gradient(ellipse at 50% 0,#231d1045,transparent 60%); }
.scroll-column { min-height:0; overflow-y:auto; overscroll-behavior:contain; scrollbar-width:thin; scrollbar-color:#695332 transparent; }
.scroll-column::-webkit-scrollbar { width:5px; }
.scroll-column::-webkit-scrollbar-thumb { background:#695332; border-radius:6px; }
.left-column, .right-column { display:flex; flex-direction:column; gap:12px; padding-right:4px; padding-bottom:3px; }
.panel { flex-shrink:0; border:1px solid #51402a; border-top-color:#997747; border-radius:4px; background:linear-gradient(125deg,#231e16,#171510 70%); box-shadow:inset 0 0 0 1px #ffffff04,0 4px 12px #0004; overflow:hidden; }
.panel-heading { height:43px; display:flex; align-items:center; justify-content:space-between; padding:0 15px; border-bottom:1px solid #443622; background:linear-gradient(95deg,#332a1b,#1c1812); }
.panel-heading h2 { font-size:14px; font-weight:800; letter-spacing:.02em; margin:0; }
.eyebrow { font-size:11px; letter-spacing:1.5px; font-weight:700; color:#c8a45c; }
.quick-body { padding:14px; display:grid; grid-template-columns:1fr 1fr; gap:8px; }
.quick-body .btn { flex-direction:column; height:64px; gap:5px; }
.quick-body .btn svg { width:18px; height:18px; }
.quick-body .btn:last-child { grid-column:span 2; flex-direction:row; height:38px; }
.search-wrap { margin:14px; }
.search-label { display:block; margin-bottom:8px; color:#d8ccb6; font-weight:700; }
.search-box { display:flex; align-items:center; padding:0 10px; border:1px solid #55452e; border-radius:3px; background:#0e0d0b; }
.search-box input { width:100%; height:38px; border:0; background:none; color:#afa18a; font-size:13px; outline:none; }
.search-box svg { width:16px; height:16px; color:#9c8357; }
.sport-nav { width:100% !important; height:auto !important; background:transparent !important; }
.sport-menu { padding:6px 9px 10px; }
.sport-menu button { display:flex; align-items:center; width:100%; min-height:46px; gap:12px; padding:0 12px; border:1px solid transparent; background:none; color:#bcaf99; text-align:left; font-size:14px; border-radius:3px; }
.sport-menu button:hover, .sport-menu button.active { background:linear-gradient(90deg,#5e492940,#32271815); border-color:#685131; color:#efdbaa; }
.sport-menu button span { flex:1; }
.sport-menu button small { font-size:12px; color:#a28d65; }
.sport-menu button svg:last-child { width:13px; }
.promo { position:relative; padding:23px 19px 18px; background:repeating-linear-gradient(120deg,transparent 0 10px,#ddbc6703 10px 11px),linear-gradient(125deg,#342b19,#18150f 75%); }
.promo::before { content:''; position:absolute; inset:6px; border:1px solid #7e602b60; pointer-events:none; }
.promo .eyebrow { position:relative; }
.promo h2 { margin:11px 0; font-size:25px; line-height:1.35; font-weight:800; letter-spacing:-.04em; }
.promo h2 em { color:#eed49a; font-style:normal; }
.promo p { color:#b9aa8e; font-size:13px; line-height:1.65; margin:0 0 18px; }
.promo .btn { width:100%; position:relative; }
.promo-footer { margin-top:13px; text-align:center; color:#837458; letter-spacing:2px; font-size:10px; }
.left-footer { padding:16px 13px 20px; color:#81745e; font-size:12px; line-height:1.8; border-top:1px solid #33291a; }
.left-footer strong { color:#b7a079; display:block; font-size:14px; letter-spacing:3px; margin-bottom:5px; }
.center-column { padding:0 3px 24px 0; }
.section-block { margin-bottom:28px; }
.section-title { height:68px; display:flex; align-items:center; justify-content:space-between; padding:0 21px; position:relative; border:1px solid var(--title-border); border-radius:4px 4px 0 0; background:linear-gradient(110deg,#392d1c,#1d1912 60%,#292115); box-shadow:inset 0 1px 0 #ebcf8650,inset 0 -4px 0 #08070544,0 4px 10px #0004; }
.section-title::before, .section-title::after { content:''; position:absolute; width:26px; height:4px; background:linear-gradient(90deg,#8b652b,#ead098); opacity:var(--title-ornament-opacity); top:-2px; }
.section-title::before { left:17px; }.section-title::after { right:17px; }
.title-group { display:flex; align-items:center; gap:12px; }
.title-icon { color:#d5b674; display:grid; place-items:center; border-right:1px solid #66502e; padding-right:14px; }
.title-icon svg { width:23px; height:23px; }
.section-title h1, .section-title h2 { margin:0; font-size:23px; font-weight:800; letter-spacing:-.7px; }
.title-right { display:flex; align-items:center; gap:10px; font-size:13px; color:#ac9b7d; }
.title-right strong { color:#e1c88b; font-size:18px; font-weight:700; }
.live-badge { display:inline-flex; align-items:center; gap:6px; border:1px solid #a7803c; border-radius:3px; color:#edcf8f; background:#69502638; padding:3px 7px; font-size:10px; font-weight:800; letter-spacing:1px; }
.live-dot { width:5px; height:5px; border-radius:50%; background:#f1d898; box-shadow:0 0 8px #f2c761; }
.section-subbar { height:38px; display:flex; justify-content:space-between; align-items:center; padding:0 15px; color:#95866b; font-size:12px; border:1px solid #463721; border-top:0; background:#15130f; }
.subbar-name { display:flex; align-items:center; gap:8px; color:#d1bc90; }
.subbar-name svg { width:13px; height:13px; }
.card-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; padding-top:12px; }
.match-card { position:relative; border:1px solid #5a452a; border-top-color:#a58043; border-radius:4px; padding:0 14px 14px; overflow:hidden; background:linear-gradient(130deg,#292218,#1a1711 60%,#211c14); box-shadow:inset 0 0 0 1px #edcc8807,0 5px 15px #0005; isolation:isolate; }
.match-card::after { content:''; position:absolute; inset:0; pointer-events:none; z-index:-1; background:linear-gradient(115deg,transparent 12%,#f8d68e50 38%,#fff5d975 46%,transparent 67%); opacity:0; transition:opacity var(--hover-duration); }
.match-card:hover::after { opacity:var(--card-hover-shine); }
.card-top { display:flex; align-items:center; gap:7px; height:40px; border-bottom:1px solid #ad884629; color:#c0b092; font-size:12px; }
.card-top svg { color:#baa16b; width:14px; height:14px; }
.card-top .market-count { margin-left:auto; border:1px solid #564327; color:#bfa66f; border-radius:3px; padding:1px 5px; font-size:10px; }
.match-status { padding:12px 0 8px; font-size:12px; color:#dabd7d; display:flex; align-items:center; gap:6px; }
.match-status i { width:4px; height:4px; background:#c9a256; border-radius:50%; }
.teams { display:grid; grid-template-columns:minmax(0,1fr) 35px; grid-auto-rows:44px; align-items:center; column-gap:8px; margin-bottom:12px; }
.team-name { display:flex; align-items:center; gap:9px; min-width:0; font-size:16px; font-weight:700; line-height:1.3; }
.team-name span:last-child { overflow-wrap:anywhere; }
.team-code { display:grid; place-items:center; font-size:9px; font-weight:500; letter-spacing:.5px; color:#bfa675; width:25px; height:25px; flex-shrink:0; border:1px solid #72592e; border-radius:50%; background:#0d0c0a; }
.score { text-align:right; color:#f3e5c7; font-size:23px; font-weight:800; line-height:1.4; }
.market { margin-top:10px; }
.market-label { display:flex; justify-content:space-between; font-size:12px; color:#a89980; margin-bottom:5px; }
.market-label .line { color:#d3bd90; font-variant-numeric:tabular-nums; }
.odds-row { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:6px; }
.odds-row.three { grid-template-columns:repeat(3,minmax(0,1fr)); }
.odd { width:100%; min-width:0; display:flex; justify-content:space-between; align-items:center; gap:5px; min-height:42px; padding:8px 10px; border:1px solid #6a5231; border-radius:3px; color:#c1b397; background:linear-gradient(#342b1d,#221d15); box-shadow:inset 0 1px 0 #d0ad5930,0 2px 3px #0005; font-size:12px; text-align:left; transition:background 160ms,border-color 160ms,box-shadow 160ms; }
.odd strong { font-size:16px; color:#eeddb6; letter-spacing:.15px; }
.odd .odd-value { display:flex; gap:3px; align-items:center; flex-shrink:0; }
.odd .trend { font-size:8px; color:#c6a45a; }
.odd:hover:not(:disabled) { background:linear-gradient(#6b5231,#382b1a); border-color:#d0ab68; box-shadow:inset 0 1px 0 #f6daa26b,0 0 14px #d0a65d35; }
.odd:active:not(:disabled), .odd[data-pressed] { transition:none; background:#a7864d; box-shadow:inset 0 3px 7px #140f09b0; transform:translateY(1px); }
.odd[aria-pressed=true] { color:#251b0d; background:linear-gradient(110deg,#a9803e,#ecd5a0 50%,#bb954f); border-color:#f3d89e; box-shadow:inset 0 1px 0 #fff4,0 0 10px #d6ad4928; }
.odd[aria-pressed=true] strong, .odd[aria-pressed=true] .trend { color:#21190c; }
.odd[aria-pressed=true]:hover { background:linear-gradient(110deg,#ba9657,#f4dfaf,#d0ad67); }
.odd:disabled { color:#766d5c; background:repeating-linear-gradient(135deg,#1b1813 0 6px,#1d1a14 6px 7px); border-color:#3b3325; box-shadow:none; opacity:1; }
.odd:disabled strong { color:#7c725f; }.odd:disabled svg { width:12px; height:12px; color:#968568; }
.card-bottom { display:flex; justify-content:space-between; padding-top:13px; margin-top:12px; border-top:1px solid #65503255; color:#81745c; font-size:10px; letter-spacing:.6px; }
.account-body { padding:14px; }
.account-identity { display:flex; gap:10px; align-items:center; margin-bottom:14px; }
.avatar { display:grid; place-items:center; width:36px; height:36px; border:1px solid #806338; background:#332818; color:#d4b575; border-radius:50%; }
.account-identity strong { display:block; font-size:14px; }.account-identity small { font-size:11px; color:#9f8d6d; }
.wallet { display:flex; justify-content:space-between; border-block:1px solid #4a3921; padding:11px 0; font-size:13px; color:#a99a7d; }
.wallet strong { color:#ead7ac; font-size:19px; line-height:1; }
.account-actions { display:grid; grid-template-columns:repeat(3,1fr); gap:6px; margin-top:12px; }.account-actions .btn { font-size:12px; padding:6px 5px; }
.slip .panel-heading { height:49px; }.slip .panel-heading h2 { font-size:17px; }
.count-badge { border:1px solid #a28042; color:#ead196; border-radius:3px; min-width:24px; padding:0 5px; display:inline-block; text-align:center; font-size:12px; margin-left:7px; }
.icon-button { border:0; background:none; color:#a18e6a; padding:5px; display:grid; place-items:center; }
.icon-button:hover { color:#f1d79d; }.icon-button:disabled { color:#645b49; }
.slip-type { display:flex; justify-content:space-between; align-items:center; height:34px; border-bottom:1px solid #41331f; margin:0 14px; font-size:12px; color:#c5b184; }
.slip-type .muted { font-size:11px; }
.slip-list { max-height:270px; overflow-y:auto; overscroll-behavior:contain; scrollbar-width:thin; scrollbar-color:#6b5534 transparent; padding:0 14px; }
.empty-slip { min-height:171px; padding:24px 10px; gap:9px; color:#c3b294; }
.empty-slip svg { width:30px; height:30px; color:#9c7a43; }
.empty-slip [data-slot=empty-title] { font-size:14px; font-weight:700; }
.empty-slip [data-slot=empty-description] { font-size:12px; color:#928268; }
.slip-item { position:relative; padding:13px 0; border-bottom:1px solid #51402a; }
.slip-item-top { display:flex; justify-content:space-between; align-items:center; color:#ae9565; font-size:10px; letter-spacing:.5px; }
.slip-item .icon-button { padding:0; }.slip-item .icon-button svg { width:14px; height:14px; }
.slip-teams { margin:5px 14px 8px 0; font-size:12px; line-height:1.55; color:#cfc0a4; }
.slip-pick { display:flex; justify-content:space-between; gap:10px; align-items:center; font-size:13px; color:#e6cca0; }.slip-pick strong { color:#f0d99e; font-size:17px; }
.slip-market { display:block; margin-top:3px; color:#907f62; font-size:11px; }
.slip-totals { padding:14px; background:linear-gradient(#282116,#1a1610); border-top:1px solid #755a2f; }
.stake-label { display:flex; justify-content:space-between; margin-bottom:7px; color:#b8a787; font-size:12px; }
.stake { width:100%; height:40px; border:1px solid #59472b; background:#0e0d0a; border-radius:3px; padding:0 12px; text-align:right; color:#9d8d70; font-variant-numeric:tabular-nums; font-size:17px; }
.stake-quick { display:grid; grid-template-columns:repeat(3,1fr); gap:5px; margin-top:6px; }.stake-quick .btn { min-height:28px; padding:3px; font-size:11px; }
.total-line { display:flex; justify-content:space-between; margin-top:14px; color:#b6a88e; font-size:13px; }.total-line strong { color:#f0d99e; font-size:17px; }
.total-line.payout { margin:7px 0 15px; }.total-line.payout strong { font-size:23px; color:#bba675; }
.submit-slip { width:100%; min-height:43px; }
.slip-footnote { font-size:10px; color:#988565; text-align:center; margin-top:9px; }
.support-links { padding:7px 14px; }.support-links button { display:flex; align-items:center; justify-content:space-between; width:100%; min-height:40px; color:#c6b79b; border:0; border-bottom:1px solid #43351f; background:none; font-size:13px; }.support-links button:last-child { border:0; }.support-links button svg { width:14px; }
.mini-event { padding:20px; }.mini-event h2 { font-size:21px; line-height:1.4; margin:8px 0 6px; color:#e9d4a3; }.mini-event p { font-size:12px; color:#a99673; }.mini-event .btn { margin-top:8px; width:100%; }
.demo-note { margin:0; padding:8px 8px 20px; font-size:11px; color:#827358; line-height:1.8; }
.inline-notice { position:fixed; bottom:24px; left:50%; transform:translateX(-50%); max-width:550px; padding:13px 18px; background:#32291c; border:1px solid #b99351; border-radius:4px; box-shadow:0 8px 30px #000b; color:#efdfbd; z-index:10; display:flex; gap:20px; align-items:center; }
.inline-notice button { background:none; border:0; color:#e8cc93; }

